<?php
require __DIR__ . '/../app/bootstrap.php'; require_login(); $pdo=db();
$totals=$pdo->query("SELECT COUNT(*) total, SUM(CASE WHEN status='Open' THEN 1 ELSE 0 END) open_count, SUM(CASE WHEN status='Returned' THEN 1 ELSE 0 END) returned_count, SUM(CASE WHEN status='Claimed' THEN 1 ELSE 0 END) claimed_count FROM items")->fetch();
$byCategory=$pdo->query("SELECT category, COUNT(*) total, SUM(CASE WHEN kind='Lost' THEN 1 ELSE 0 END) lost_count, SUM(CASE WHEN kind='Found' THEN 1 ELSE 0 END) found_count FROM items GROUP BY category ORDER BY total DESC, category")->fetchAll();
if ($pdo->getAttribute(PDO::ATTR_DRIVER_NAME) === 'pgsql') {
    $monthly=$pdo->query("SELECT TO_CHAR(created_at,'YYYY-MM') month, COUNT(*) total, SUM(CASE WHEN kind='Lost' THEN 1 ELSE 0 END) lost_count, SUM(CASE WHEN kind='Found' THEN 1 ELSE 0 END) found_count FROM items WHERE created_at >= CURRENT_DATE - INTERVAL '6 months' GROUP BY TO_CHAR(created_at,'YYYY-MM') ORDER BY month")->fetchAll();
} else {
    $monthly=$pdo->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month, COUNT(*) total, SUM(CASE WHEN kind='Lost' THEN 1 ELSE 0 END) lost_count, SUM(CASE WHEN kind='Found' THEN 1 ELSE 0 END) found_count FROM items WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 6 MONTH) GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY month")->fetchAll();
}
$claims=$pdo->query('SELECT status, COUNT(*) total FROM claims GROUP BY status')->fetchAll(); $claimMap=[]; foreach($claims as $c)$claimMap[$c['status']]=(int)$c['total']; $maxCategory=max(array_map(fn($r)=>(int)$r['total'],$byCategory) ?: [1]); $maxMonthly=max(array_map(fn($r)=>(int)$r['total'],$monthly) ?: [1]);
page_start('Community reports','reports'); ?><div class="section-head"><div><span class="eyebrow">CAMPUS ACTIVITY</span><h1>Community reports</h1><p class="muted">Live summaries across all SokoFind listings.</p></div><span class="report-date">Updated <?= date('M j, Y') ?></span></div><div class="stat-grid"><article class="stat-card"><span>Total listings</span><strong><?= (int)($totals['total']??0) ?></strong><small>All time</small></article><article class="stat-card"><span>Open listings</span><strong><?= (int)($totals['open_count']??0) ?></strong><small>Needs attention</small></article><article class="stat-card"><span>Returned</span><strong><?= (int)($totals['returned_count']??0) ?></strong><small>Marked returned</small></article><article class="stat-card"><span>Claims</span><strong><?= array_sum($claimMap) ?></strong><small><?= (int)($claimMap['Pending']??0) ?> pending</small></article></div><div class="reports-grid"><section class="report-panel"><div class="panel-heading"><div><span class="eyebrow">REPORT 1</span><h2>Items by category</h2></div><span class="muted">Category mix</span></div><?php if(!$byCategory): ?><p class="muted">No listings yet.</p><?php else: ?><div class="bar-list"><?php foreach($byCategory as $r): ?><div class="bar-row"><div class="bar-label"><span><?= e($r['category']) ?></span><strong><?= (int)$r['total'] ?></strong></div><div class="bar-track"><span style="width:<?= round(100*(int)$r['total']/$maxCategory) ?>%"></span></div><small><?= (int)$r['lost_count'] ?> lost · <?= (int)$r['found_count'] ?> found</small></div><?php endforeach; ?></div><?php endif; ?></section><section class="report-panel"><div class="panel-heading"><div><span class="eyebrow">REPORT 2</span><h2>Recent monthly activity</h2></div><span class="muted">Last 6 months</span></div><?php if(!$monthly): ?><p class="muted">No activity yet.</p><?php else: ?><div class="bar-list"><?php foreach($monthly as $r): ?><div class="bar-row"><div class="bar-label"><span><?= e(date('M Y',strtotime($r['month'].'-01'))) ?></span><strong><?= (int)$r['total'] ?></strong></div><div class="bar-track"><span class="bar-accent" style="width:<?= round(100*(int)$r['total']/$maxMonthly) ?>%"></span></div><small><?= (int)$r['lost_count'] ?> lost · <?= (int)$r['found_count'] ?> found</small></div><?php endforeach; ?></div><?php endif; ?></section><section class="report-panel full-panel"><div class="panel-heading"><div><span class="eyebrow">REPORT 3</span><h2>Listing status summary</h2></div><span class="muted">Current outcomes</span></div><div class="status-table-wrap"><table><thead><tr><th>Outcome</th><th>Listings</th><th>Share</th></tr></thead><tbody><?php foreach(['Open'=>'open_count','Claimed'=>'claimed_count','Returned'=>'returned_count'] as $label=>$key): $n=(int)($totals[$key]??0); $all=(int)($totals['total']??0); ?><tr><td><span class="status status-<?= strtolower($label) ?>"><?= e($label) ?></span></td><td><?= $n ?></td><td><?= $all?round($n*100/$all):0 ?>%</td></tr><?php endforeach; ?></tbody></table></div><div class="claim-summary"><span>Claims by decision</span><span>Pending <strong><?= (int)($claimMap['Pending']??0) ?></strong></span><span>Accepted <strong><?= (int)($claimMap['Accepted']??0) ?></strong></span><span>Declined <strong><?= (int)($claimMap['Declined']??0) ?></strong></span></div></section></div><?php page_end(); ?>
